<script setup lang="ts">
import { ref, watch } from 'vue'
import { qtrc, useLanguage } from '../../../i18n'
import { ICON_CODES } from '../../../actions/uiactiondata'
import type { NotationStyleLike } from './controls.vue'
const props=defineProps<{style:NotationStyleLike;goToTextStylePage?:(id:string|number)=>void}>()
useLanguage()
const tr=(s:string)=>qtrc('notation/editstyle/bends',s)
const fields=[['guitarBendLineWidth',0.01],['guitarBendLineWidthTab',0.01],['guitarBendArrowWidth',0.1],['guitarBendArrowHeight',0.1],['guitarDiveLineWidth',0.01],['guitarDiveLineWidthTab',0.01],['whammyBarLineWidth',0.1],['whammyBarDashLineLen',0.1],['whammyBarDashGapLen',0.1]] as const
const values=ref<Record<string,string>>(Object.fromEntries(fields.map(([id])=>[id,String(props.style.value(id) ?? 0)])))
watch(()=>fields.map(([id])=>props.style.value(id)),v=>fields.forEach(([id],i)=>{values.value[id]=String(v[i] ?? 0)}))
function commit(id:string){const n=parseFloat(values.value[id].replace(',','.'));if(Number.isFinite(n))props.style.setValue(id,Number(Math.max(0,Math.min(99,n)).toFixed(2)));values.value[id]=String(props.style.value(id) ?? 0)}
function step(id:string,d:number){values.value[id]=String((parseFloat(values.value[id].replace(',','.'))||0)+d);commit(id)}
const spin=(id:string,label:string,increment:number)=>({id,label,increment})
const lineFields=[spin('whammyBarLineWidth','Line thickness:',0.1),spin('whammyBarDashLineLen','Dash (dashed line):',0.1),spin('whammyBarDashGapLen','Gap (dashed line):',0.1)]
</script>
<template>
<div class="sd-column" style="gap:12px">
  <fieldset v-for="section in [{title:'Bends',standard:spin('guitarBendLineWidth','Line thickness:',0.01),tab:spin('guitarBendLineWidthTab','Line thickness:',0.01)},{title:'Dives',standard:spin('guitarDiveLineWidth','Line thickness:',0.01),tab:spin('guitarDiveLineWidthTab','Line thickness:',0.01)}]" :key="section.title" class="sd-groupbox" style="min-width:500px"><legend>{{ tr(section.title) }}</legend><div class="sd-column" style="gap:8px">
    <fieldset v-for="kind in ['Standard staff','Tablature staff']" :key="kind" class="sd-groupbox"><legend>{{ tr(kind) }}</legend><div class="sd-column" :style="{gap:kind==='Tablature staff'?'8px':'12px'}">
      <template v-if="section.title==='Dives' && kind==='Tablature staff'"><span class="sd-label">{{ tr('Show dive lines') }}</span><div class="sd-column" role="radiogroup" style="gap:8px"><label v-for="(label,index) in ['On the staff','Above the staff']" :key="label" class="sd-radio"><input type="radio" name="dives" :checked="style.value('guitarDivesAboveStaff')===(index===1)" @change="style.setValue('guitarDivesAboveStaff',index===1)"><span>{{ tr(label) }}</span></label></div></template>
      <div v-for="f in [kind==='Standard staff'?section.standard:section.tab]" :key="f.id" class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px"><span class="sd-label">{{ tr(f.label) }}</span></div><div class="sd-row-control" style="width:100px"><div class="sd-spinbox" style="width:80px"><input v-model="values[f.id]" type="text" inputmode="decimal" :aria-label="tr(f.label)" @blur="commit(f.id)" @keydown.enter.prevent="commit(f.id)" @keydown.up.prevent="step(f.id,f.increment)" @keydown.down.prevent="step(f.id,-f.increment)"><span class="sd-unit">{{ qtrc('global','sp') }}</span><span class="sd-steppers"><button type="button" tabindex="-1" aria-label="+" @mousedown.prevent @click="step(f.id,f.increment)">{{ String.fromCodePoint(ICON_CODES.SMALL_ARROW_UP) }}</button><button type="button" tabindex="-1" aria-label="-" @mousedown.prevent @click="step(f.id,-f.increment)">{{ String.fromCodePoint(ICON_CODES.SMALL_ARROW_DOWN) }}</button></span></div></div><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="style.resetValue?.(f.id)"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div>
      <template v-if="section.title==='Bends' && kind==='Tablature staff'"><div class="sd-row" style="gap:12px"><div v-for="f in [spin('guitarBendArrowWidth','Arrow width:',0.1),spin('guitarBendArrowHeight','Arrow height:',0.1)]" :key="f.id" class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px"><span class="sd-label">{{ tr(f.label) }}</span></div><div class="sd-row-control" style="width:100px"><div class="sd-spinbox" style="width:80px"><input v-model="values[f.id]" type="text" inputmode="decimal" :aria-label="tr(f.label)" @blur="commit(f.id)" @keydown.enter.prevent="commit(f.id)" @keydown.up.prevent="step(f.id,f.increment)" @keydown.down.prevent="step(f.id,-f.increment)"><span class="sd-unit">{{ qtrc('global','sp') }}</span><span class="sd-steppers"><button type="button" tabindex="-1" aria-label="+" @mousedown.prevent @click="step(f.id,f.increment)">{{ String.fromCodePoint(ICON_CODES.SMALL_ARROW_UP) }}</button><button type="button" tabindex="-1" aria-label="-" @mousedown.prevent @click="step(f.id,-f.increment)">{{ String.fromCodePoint(ICON_CODES.SMALL_ARROW_DOWN) }}</button></span></div></div><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="style.resetValue?.(f.id)"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div></div><div class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px"><span class="sd-label">{{ tr('Label for full bends:') }}</span></div><div class="sd-row-control" style="width:326px"><div class="sd-flat-radio-group" role="radiogroup" style="gap:4px"><button v-for="(icon,index) in [ICON_CODES.GUITAR_BEND_STYLE_1,ICON_CODES.GUITAR_BEND_STYLE_FULL]" :key="index" type="button" role="radio" class="sd-flat-radio stacked" style="width:106px;height:60px;flex:0 0 auto" :aria-checked="style.value('guitarBendUseFull')===(index===1)" @click="style.setValue('guitarBendUseFull',index===1)"><span class="sd-icon" style="font-size:28px">{{ String.fromCodePoint(icon) }}</span></button></div></div></div></template>
    </div></fieldset>
    <fieldset v-if="section.title==='Dives'" class="sd-groupbox"><legend>{{ tr('Whammy bar line') }}</legend><div class="sd-column" style="gap:8px"><div class="sd-row" style="gap:12px"><div class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px"><span class="sd-label">{{ tr('Text label:') }}</span></div><div class="sd-row-control" style="width:100px"><input class="sd-text" style="width:100px" :aria-label="tr('Text label:')" :value="style.value('whammyBarText')" @change="style.setValue('whammyBarText',($event.target as HTMLInputElement).value)"></div><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="style.resetValue?.('whammyBarText')"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div><div class="sd-vseparator"></div><button type="button" class="sd-flat-button" @click="goToTextStylePage?.('whammy-bar')">{{ qtrc('notation','Edit text style') }}</button></div><div class="sd-column" style="gap:12px"><div class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px"><span class="sd-label">{{ qtrc('notation','Line style:') }}</span></div><div class="sd-row-control" style="width:326px"><div class="sd-flat-radio-group" role="radiogroup" :aria-label="qtrc('notation','Line style:')" style="gap:4px"><button v-for="(icon,index) in [ICON_CODES.LINE_NORMAL,ICON_CODES.LINE_DASHED,ICON_CODES.LINE_DOTTED]" :key="index" type="button" role="radio" class="sd-flat-radio" :aria-label="qtrc('notation',['Normal','Dashed','Dotted'][index])" :aria-checked="style.value('whammyBarLineStyle')===index" @click="style.setValue('whammyBarLineStyle',index)"><span class="sd-icon" aria-hidden="true">{{ String.fromCodePoint(icon) }}</span></button></div></div><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="style.resetValue?.('whammyBarLineStyle')"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div><div v-for="f in lineFields" :key="f.id" class="sd-row sd-control-row" style="gap:8px"><div class="sd-row-label" style="width:120px"><span class="sd-label">{{ qtrc('notation',f.label) }}</span></div><div class="sd-row-control" style="width:326px"><div class="sd-spinbox" style="width:80px"><input v-model="values[f.id]" type="text" inputmode="decimal" :aria-label="qtrc('notation',f.label)" @blur="commit(f.id)" @keydown.enter.prevent="commit(f.id)" @keydown.up.prevent="step(f.id,f.increment)" @keydown.down.prevent="step(f.id,-f.increment)"><span v-if="f.id==='whammyBarLineWidth'" class="sd-unit">{{ qtrc('global','sp') }}</span><span class="sd-steppers"><button type="button" tabindex="-1" aria-label="+" @mousedown.prevent @click="step(f.id,f.increment)">{{ String.fromCodePoint(ICON_CODES.SMALL_ARROW_UP) }}</button><button type="button" tabindex="-1" aria-label="-" @mousedown.prevent @click="step(f.id,-f.increment)">{{ String.fromCodePoint(ICON_CODES.SMALL_ARROW_DOWN) }}</button></span></div></div><button type="button" class="sd-flat-button icon-only" :aria-label="qtrc('global','Reset')" @click="style.resetValue?.(f.id)"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div></div></div></fieldset>
  </div></fieldset>
  <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{ tr('Grace note bends/dives on tablature') }}</legend><div class="sd-column" style="gap:12px"><label class="sd-checkbox"><input type="checkbox" :checked="style.value('useCueSizeFretForGraceBends')===true" @change="style.setValue('useCueSizeFretForGraceBends',!style.value('useCueSizeFretForGraceBends'))"><span>{{ tr('Use cue sized fret numbers') }}</span></label><div class="sd-column" style="gap:8px"><span class="sd-label">{{ tr('Align pre-bends and pre-dives') }}</span><div class="sd-column" role="radiogroup" style="gap:8px"><label v-for="(label,index) in ['To the main note','To the grace note']" :key="label" class="sd-radio"><input type="radio" name="grace-align" :checked="style.value('alignPreBendAndPreDiveToGraceNote')===(index===1)" @change="style.setValue('alignPreBendAndPreDiveToGraceNote',index===1)"><span>{{ tr(label) }}</span></label></div></div></div></fieldset>
  <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{ tr('Interval labels') }}</legend><div class="sd-column" style="gap:12px"><div class="sd-row" style="gap:12px"><div class="sd-flat-radio-group" role="radiogroup" style="gap:4px"><button v-for="(item,index) in [{icon:ICON_CODES.FRACTION_DIAGONAL,label:'Diagonal',value:true},{icon:ICON_CODES.FRACTION_LEVEL,label:'Level',value:false}]" :key="index" type="button" role="radio" class="sd-flat-radio stacked" style="width:132px;height:52px;flex:0 0 auto" :aria-checked="style.value('useFractionCharacters')===item.value" @click="style.setValue('useFractionCharacters',item.value)"><span class="sd-icon" aria-hidden="true">{{ String.fromCodePoint(item.icon) }}</span>{{ tr(item.label) }}</button></div><div class="sd-vseparator"></div><button type="button" class="sd-flat-button" @click="goToTextStylePage?.('bend')">{{ qtrc('notation','Edit text style') }}</button></div></div></fieldset>
</div>
</template>
